for i from n-1 downto 0:
  for j from n-1 downto 0:
    if board[i][j] == 'X': mark unreachable
    elif (i,j) is S: sum=0, ways=1
    else:
      best = max reachable sum among (i+1,j), (i,j+1), (i+1,j+1)
      ways = sum of ways over predecessors whose sum == best
      this sum = best + value(board[i][j])
  roll current row into previous row
return [sum at E, ways at E]  (or [0,0] if E unreachable)
