class Solution {
public:
    vector<int> pathsWithMaxScore(vector<string>& board) {
        int n = board.size();
        const long long MOD = 1000000007;
        vector<long long> prevDp(n, -1), prevWays(n, 0);
        vector<long long> curDp(n), curWays(n);
        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                char c = board[i][j];
                if (c == 'X') {
                    curDp[j] = -1;
                    curWays[j] = 0;
                    continue;
                }
                if (i == n - 1 && j == n - 1) {
                    curDp[j] = 0;
                    curWays[j] = 1;
                    continue;
                }
                long long val = (c == 'E' || c == 'S') ? 0 : (c - '0');
                long long best = -1;
                long long cnt = 0;
                if (i + 1 < n && prevDp[j] >= 0) {
                    if (prevDp[j] > best) { best = prevDp[j]; cnt = prevWays[j]; }
                    else if (prevDp[j] == best) { cnt = (cnt + prevWays[j]) % MOD; }
                }
                if (j + 1 < n && curDp[j + 1] >= 0) {
                    if (curDp[j + 1] > best) { best = curDp[j + 1]; cnt = curWays[j + 1]; }
                    else if (curDp[j + 1] == best) { cnt = (cnt + curWays[j + 1]) % MOD; }
                }
                if (i + 1 < n && j + 1 < n && prevDp[j + 1] >= 0) {
                    if (prevDp[j + 1] > best) { best = prevDp[j + 1]; cnt = prevWays[j + 1]; }
                    else if (prevDp[j + 1] == best) { cnt = (cnt + prevWays[j + 1]) % MOD; }
                }
                if (best < 0) {
                    curDp[j] = -1;
                    curWays[j] = 0;
                } else {
                    curDp[j] = best + val;
                    curWays[j] = cnt;
                }
            }
            swap(prevDp, curDp);
            swap(prevWays, curWays);
        }
        if (prevDp[0] < 0) return {0, 0};
        return {(int)prevDp[0], (int)prevWays[0]};
    }
};
